<script setup>
const {user,send,busy,date}=useReiki()
const {data:entries,error,refresh}=await useFetch('/api/account/journal',{immediate:!!user.value,default:()=>[]})
const empty=()=>({id:null,title:'',body:'',mood:'',entry_date:new Date().toISOString().slice(0,10)})
const form=reactive(empty()),q=ref(''),deleting=ref(null)
const filtered=computed(()=>(entries.value||[]).filter(e=>(e.title+' '+e.body+' '+e.mood).includes(q.value)))
async function save(){if(await send('/api/account/journal',form)){Object.assign(form,empty());await refresh()}}
async function remove(){if(await send('/api/account/journal',{id:deleting.value,action:'delete'})){deleting.value=null;await refresh()}}
function edit(e){Object.assign(form,e);window.scrollTo({top:0,behavior:'smooth'})}
</script>
<template><main class="page"><div class="page-heading"><small>فقط برای تو</small><h1>دفتر آرام من</h1><p>لازم نیست زیبا بنویسی؛ فقط صادق باش.</p></div><NuxtLink v-if="!user" to="/profile" class="btn btn-primary">برای نوشتن وارد شو</NuxtLink><template v-else><form class="card" @submit.prevent="save"><label class="field"><span>عنوان نوشته</span><input v-model="form.title" class="input" required maxlength="160" placeholder="امروز متوجه شدم…"/></label><label class="field"><span>نوشتهٔ تو</span><textarea v-model="form.body" class="textarea journal-paper" maxlength="30000" placeholder="از همین‌جا شروع کن…"/></label><label class="field"><span>حس امروز</span><input v-model="form.mood" class="input" maxlength="80" placeholder="مثلاً آرام، خسته، امیدوار"/></label><label class="field"><span>تاریخ ثبت (میلادی؛ نمایش نوشته‌ها شمسی است)</span><input v-model="form.entry_date" type="date" class="input" required/></label><div class="row"><button class="btn btn-primary" :disabled="busy">{{form.id?'ذخیرهٔ ویرایش':'نگه‌داشتن این لحظه'}}</button><button v-if="form.id" type="button" class="btn btn-ghost" @click="Object.assign(form,empty())">انصراف</button></div></form><p class="disclaimer">نوشته‌ها فقط در حساب خودت قابل مشاهده‌اند؛ مدیر از پنل به متن ژورنال دسترسی ندارد. ذخیره‌سازی این نسخه رمزنگاری سرتاسری نیست.</p><label class="field"><span>جست‌وجو در نوشته‌های خودت</span><input v-model="q" class="input" placeholder="کلمه‌ای از نوشته…"/></label><p v-if="error">دریافت نوشته‌ها ممکن نشد.</p><div class="stack"><article v-for="entry in filtered" :key="entry.id" class="card"><small>{{date(entry.entry_date)}} · {{entry.mood}}</small><h3>{{entry.title}}</h3><p class="prose">{{entry.body}}</p><div class="row"><button class="btn btn-ghost btn-sm" @click="edit(entry)">ویرایش</button><button class="btn btn-ghost btn-sm" @click="deleting=entry.id">حذف</button></div><div v-if="deleting===entry.id" role="alert"><p>این نوشته برای همیشه حذف شود؟</p><button class="btn btn-primary" :disabled="busy" @click="remove">بله، حذف شود</button><button class="btn" @click="deleting=null">انصراف</button></div></article><div v-if="!filtered.length" class="state">هنوز نوشته‌ای اینجا نیست. با یک جمله شروع کن.</div></div></template></main></template>
